    Examples
    solve("1234") = "4321"
    solve("ab") = "AB"
    solve("#a@C") = "#A@c"
    """
    result = ""
    for char in s:
        if char.isalpha():
            if char.isupper():
                result = char.lower() + result
            else:
                result = char.upper() + result
        else:
            result += char
